/**
 * Facts Extractor — facts.extractor.js (V2)
 *
 * Produces a canonical `facts` object from the repository's static knowledge.
 * Every field in this object is derived from code, manifest files, .env files,
 * or infrastructure specs — nothing is inferred or generated by AI.
 *
 * V2 CHANGE
 * ─────────
 * V1 read directly from JS-specific knowledge fields (knowledge.ast.envVars,
 * Object.keys(pkg.dependencies), etc.). This broke for non-JS ecosystems where
 * those fields are empty.
 *
 * V2 reads from the Common Fact Model (knowledge.facts[]) first, then falls
 * back to the legacy JS-specific fields for backward compatibility with repos
 * that haven't been re-analyzed with the V2 orchestrator.
 *
 * USAGE
 * ─────
 * 1. Grounding constraint: the prompt tells the model it may only reference
 *    names that appear in the facts object (packages, routes, env vars,
 *    scripts). Anything not in facts should not appear in the README.
 *
 * 2. Critic pass: the critic scans the generated README for identifiers and
 *    checks each one against facts. Unrecognised identifiers are flagged.
 *
 * All fields are normalised (lowercase, trimmed) for consistent comparison.
 */

import * as Fact from "./core/fact.schema.js";

/**
 * Extracts the canonical facts object from a knowledge tree.
 *
 * @param {object} knowledge - Output of repositoryAnalyzer.analyzeRepository()
 * @returns {object} facts
 */
export const extractFacts = (knowledge) => {
    if (!knowledge) {
        return emptyFacts();
    }

    // ── Project name ──────────────────────────────────────────────────────
    const pkg         = knowledge.package?.project || {};
    const projectName = (pkg.name || "").trim();

    // ── Dependencies ──────────────────────────────────────────────────────
    // V2: read from the normalized dependency list in knowledge.package
    const dependencies    = knowledge.package?.runtimeDependencies || Object.keys(pkg.dependencies || {});
    const devDependencies = knowledge.package?.devDependencies     || Object.keys(pkg.devDependencies || {});

    // ── npm/yarn scripts ──────────────────────────────────────────────────
    const scripts = Object.entries(knowledge.package?.scripts || pkg.scripts || {})
        .map(([name, command]) => ({ name, command }));

    // ── Routes / Endpoints ────────────────────────────────────────────────
    // V2: prefer Common Fact Model endpoint facts (all ecosystems)
    //     Fall back to legacy knowledge.routes for JS repos
    let routes;
    if (knowledge.facts && knowledge.facts.length > 0) {
        const endpointFacts = Fact.getEndpoints(knowledge.facts);
        routes = endpointFacts
            .filter(f => f.method && f.path)
            .map(f => ({
                method:     f.method.toUpperCase(),
                path:       f.path,
                confidence: f.confidence,
            }));
    } else {
        routes = (knowledge.routes || [])
            .filter(r => r.path && r.method)
            .map(r => ({
                method: r.method.toUpperCase(),
                path:   r.path,
            }));
    }

    // ── Environment variables ─────────────────────────────────────────────
    // V2: merge from three sources:
    //   1. Common Fact Model envvar facts (all ecosystems, all analyzers)
    //   2. AST-derived env vars (JS repos, process.env.XXX references)
    //   3. .env.example file keys (JS repos, legacy shape)

    const envVarFacts    = Fact.getEnvVars(knowledge.facts || []);
    const envVarsFromAst = knowledge.ast?.envVars || [];
    const envFileKeys    = (knowledge.ast?.envFileVars || []).map(e => e.key);

    const allEnvVarKeys = [
        ...envVarFacts.map(f => f.key),
        ...envVarsFromAst,
        ...envFileKeys,
    ];

    const envVars = [...new Set(allEnvVarKeys)];

    // Keys specifically from .env.example / .env.sample:
    // merge from Fact.envvar(source="file") + legacy envFileVars
    const factFileVarKeys   = envVarFacts.filter(f => f.source === "file").map(f => f.key);
    const legacyFileVarKeys = envFileKeys;
    const envFileVars = [...new Set([...factFileVarKeys, ...legacyFileVarKeys])];

    return {
        projectName,
        dependencies,
        devDependencies,
        scripts,
        routes,
        envVars,
        envFileVars,
    };
};

/**
 * Returns an empty facts object with the correct shape.
 * Used as a safe fallback when knowledge is missing.
 */
const emptyFacts = () => ({
    projectName:     "",
    dependencies:    [],
    devDependencies: [],
    scripts:         [],
    routes:          [],
    envVars:         [],
    envFileVars:     [],
});
